def _verify_search_manifest(
    manifest: List[Dict[str, Any]],
    source_paths: List[str],
) -> Tuple[int, int, List[str]]:
    """Mechanically verify the CT v2 search manifest.

    Checks that the agent's claimed searches are syntactically valid AND
    scoped to the reviewed source tree.

    Returns:
        (verified_count, total_count, issues)
    """
    verified = 0
    issues: List[str] = []
    source_abs = [os.path.realpath(str(p)) for p in source_paths]
    source_set = set(source_abs)
    allowed_dirs = {os.path.dirname(p) for p in source_abs}
    source_basenames = {os.path.basename(p): p for p in source_abs}

    def _resolve_manifest_path(raw: str) -> Optional[str]:
        if not raw:
            return None
        raw = raw.strip().strip("\"'")
        real = os.path.realpath(raw)
        if real in source_set:
            return real
        bn = os.path.basename(raw)
        if bn in source_basenames:
            return source_basenames[bn]
        for sp in source_abs:
            if sp.endswith(raw):
                return sp
        return None

    def _extract_path_tokens(raw_args: Any) -> List[str]:
        text = raw_args if isinstance(raw_args, str) else json.dumps(raw_args, sort_keys=True)
        candidates = re.findall(r'(?:[\w./-]+\.[\w]+|[\w./-]+/)', text)
        return [c for c in candidates if c not in ('Read', 'Grep', 'Glob', 'rg', 'grep', 'cat')]

    for step in manifest:
        if not isinstance(step, dict):
            issues.append(f"Malformed manifest step: {type(step).__name__}")
            continue

        tool = str(step.get("tool", ""))
        args = step.get("args", "")

        if tool in ("Read", "read", "cat"):
            file_arg = args if isinstance(args, str) else str(args)
            resolved = _resolve_manifest_path(file_arg)
            if resolved and os.path.isfile(resolved):
                verified += 1
            else:
                issues.append(f"Read target not in reviewed sources: {file_arg}")

        elif tool in ("Grep", "grep", "rg"):
            pattern = args if isinstance(args, str) else json.dumps(args, sort_keys=True)
            try:
                re.compile(pattern)
            except re.error:
                issues.append(f"Invalid grep pattern: {pattern}")
                continue

            path_tokens = _extract_path_tokens(args)
            resolved_paths = [_resolve_manifest_path(tok) for tok in path_tokens]
            if any(rp is not None for rp in resolved_paths):
                verified += 1
            else:
                issues.append(f"Grep step not scoped to reviewed sources: {pattern}")

        elif tool in ("Glob", "glob"):
            path_tokens = _extract_path_tokens(args)
            resolved_paths = [_resolve_manifest_path(tok.rstrip("/")) for tok in path_tokens]
            if any(rp is not None for rp in resolved_paths):
                verified += 1
            elif any(os.path.realpath(tok.rstrip("/")) in allowed_dirs for tok in path_tokens):
                verified += 1
            else:
                issues.append(f"Glob step not scoped to reviewed sources: {args}")

        else:
            issues.append(f"Unknown tool: {tool}")

    return verified, len(manifest), issues
